const allowed=new Set(['none','H2','H2O','Cl2','Br2','I2']);
const valence={C:4,H:1,O:2,Cl:1,Br:1,I:1,'*':1};
const sub=s=>String(s).replace(/\d/g,d=>'₀₁₂₃₄₅₆₇₈₉'[Number(d)]);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function organicDisplayOptions(options={}){const {carbons=2,reagent='none',polymer=false}=options&&typeof options==='object'?options:{};const usePolymer=polymer===true;let n;try{n=Number(carbons)}catch{n=2}return {carbons:Math.max(2,Math.min(usePolymer?3:5,Number.isFinite(n)?Math.round(n):2)),reagent:allowed.has(reagent)?reagent:'none',polymer:usePolymer};}
function graph(){return {atoms:[],bonds:[]};}
function atom(g,element,x,y){g.atoms.push({element,x,y});return g.atoms.length-1;}
function bond(g,a,b,order=1){g.bonds.push({a,b,order});}
function fillHydrogens(g,ids,spacing=40){for(const id of ids){const a=g.atoms[id];const linked=g.bonds.filter(b=>b.a===id||b.b===id);const used=linked.reduce((s,b)=>s+b.order,0);const occupied=linked.map(b=>g.atoms[b.a===id?b.b:b.a]);const directions=[[0,-1],[0,1],[-1,0],[1,0]].filter(([dx,dy])=>!occupied.some(o=>Math.abs((o.x-a.x)*dy-(o.y-a.y)*dx)<1&&(o.x-a.x)*dx+(o.y-a.y)*dy>0));const needed=valence[a.element]-used;for(let i=0;i<needed;i++){const [dx,dy]=directions[i];bond(g,id,atom(g,'H',a.x+spacing*dx,a.y+spacing*dy));}}}
export function organicDisplayGraph(options={}){const o=organicDisplayOptions(options),g=graph(),cs=[];for(let i=0;i<o.carbons;i++)cs.push(atom(g,'C',75+i*90,95));for(let i=1;i<cs.length;i++)bond(g,cs[i-1],cs[i],i===1&&o.reagent==='none'?2:1);if(['Cl2','Br2','I2'].includes(o.reagent)){const e=o.reagent.slice(0,-1);bond(g,cs[0],atom(g,e,75,145));bond(g,cs[1],atom(g,e,165,145));}if(o.reagent==='H2O'){const oxygen=atom(g,'O',165,145);bond(g,cs[1],oxygen);bond(g,oxygen,atom(g,'H',165,190));}fillHydrogens(g,cs);return {...g,options:o};}
export function organicRepeatGraph(options={}){const o=organicDisplayOptions({...options,polymer:true}),g=graph();const c0=atom(g,'C',105,95),c1=atom(g,'C',225,95);bond(g,c0,c1);bond(g,c0,atom(g,'*',40,95));bond(g,c1,atom(g,'*',330,95));const cs=[c0,c1];if(o.carbons===3){const c2=atom(g,'C',225,175);bond(g,c1,c2);cs.push(c2);}fillHydrogens(g,cs);return {...g,options:o};}
export function organicAtomCounts(g){return g.atoms.reduce((counts,a)=>{if(a.element!=='*')counts[a.element]=(counts[a.element]||0)+1;return counts;},{});}
function molecularFormula(g){const c=organicAtomCounts(g);return ['C','H','O','Cl','Br','I'].filter(e=>c[e]).map(e=>e+(c[e]===1?'':c[e])).join('');}
function renderGraph(g,{offsetX=0,offsetY=0,scale=1,repeat=false}={}){const lines=g.bonds.map(({a,b,order})=>{const p=g.atoms[a],q=g.atoms[b],dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len,start=p.element==='*'?0:13,end=q.element==='*'?0:13;return Array.from({length:order},(_,i)=>{const gap=(i-(order-1)/2)*6;return `<line x1="${p.x+ux*start-uy*gap}" y1="${p.y+uy*start+ux*gap}" x2="${q.x-ux*end-uy*gap}" y2="${q.y-uy*end+ux*gap}"/>`;}).join('');}).join('');const labels=g.atoms.filter(a=>a.element!=='*').map(a=>`<text x="${a.x}" y="${a.y+6}">${escape(a.element)}</text>`).join('');const brackets=repeat?'<path d="M82 30 H72 V238 H82 M290 30 H300 V238 H290" fill="none"/><text x="316" y="241" font-style="italic" fill="currentColor" stroke="none">n</text>':'';return `<g transform="translate(${offsetX} ${offsetY}) scale(${scale})"><g stroke="currentColor" stroke-width="2" stroke-linecap="round">${lines}${brackets}</g><g text-anchor="middle" font-family="Arial,sans-serif" font-size="18" fill="currentColor">${labels}</g></g>`;}
export function organicDisplayFigure(options={}){const o=organicDisplayOptions(options);if(o.polymer){const monomer=organicDisplayGraph({carbons:o.carbons}),repeat=organicRepeatGraph(o),name=o.carbons===2?'ethene':'propene',title=`Addition polymerisation: ${name} to its fully displayed repeat unit`;return `<div class="organic-structures"><svg class="organic-wide" viewBox="0 0 760 350" role="img" aria-label="${escape(title)}" style="width:100%;height:auto;color:inherit"><title>${escape(title)}</title><desc>Every carbon, hydrogen and bond is shown. The alkene double bond becomes a single backbone bond; all atoms are retained. Brackets, two continuation bonds and n show repetition. Geometry is symbolic, not molecular shape.</desc>${renderGraph(monomer,{offsetX:0,offsetY:30})}<text x="335" y="130" font-size="32" fill="currentColor">→</text>${renderGraph(repeat,{offsetX:390,offsetY:30,repeat:true})}<g fill="currentColor" text-anchor="middle" font-family="Arial,sans-serif" font-size="16"><text x="150" y="315">n ${sub(molecularFormula(monomer))} monomers</text><text x="590" y="315">[${sub(molecularFormula(repeat))}]ₙ · no small product</text><text x="380" y="343" font-size="13">Symbolic bond geometry. Repeat brackets cross the backbone continuation bonds.</text></g></svg><svg class="organic-stack" viewBox="0 0 380 650" role="img" aria-label="${escape(title)}" style="width:100%;height:auto;color:inherit"><title>${escape(title)}</title><desc>Fully displayed monomer and repeat unit. All atoms retained; two continuation bonds cross the brackets.</desc>${renderGraph(monomer,{offsetX:40,offsetY:0})}<text x="190" y="230" text-anchor="middle" fill="currentColor" font-size="20">n ${sub(molecularFormula(monomer))} monomers</text><text x="190" y="290" text-anchor="middle" font-size="32" fill="currentColor">↓</text>${renderGraph(repeat,{offsetX:0,offsetY:320,repeat:true})}<text x="190" y="625" text-anchor="middle" fill="currentColor" font-size="18">No small molecule product</text></svg></div>`;}
const product=organicDisplayGraph(o),monomer=organicDisplayGraph({carbons:o.carbons});const formula=molecularFormula(product),eq=o.reagent==='none'?sub(formula):`${sub(molecularFormula(monomer))} + ${sub(o.reagent)} → ${sub(formula)}`;const title=o.reagent==='none'?`Fully displayed terminal alkene with ${o.carbons} carbons`:`Fully displayed addition product: ${eq}`;const note=o.reagent==='H2O'?'One specified product: OH on carbon 2. Regioselectivity recall is not assessed.':'Every atom and bond shown. Symbolic geometry; not an actual molecular shape.';return `<svg viewBox="0 0 530 290" role="img" aria-label="${escape(title)}" style="width:100%;height:auto;color:inherit"><title>${escape(title)}</title><desc>${escape(note)} Carbon valence four; hydrogen and halogens one; oxygen two.</desc>${renderGraph(product)}<g fill="currentColor" text-anchor="middle" font-family="Arial,sans-serif"><text x="265" y="240" font-size="19">${escape(eq)}</text><text x="265" y="273" font-size="11">${escape(note)}</text></g></svg>`;}
